def _verify(iface, candidate, tentative=False, vtype=None):
    import inspect
    from zope.interface.exceptions import Invalid
    from zope.interface.verify import verifyObject, verifyClass

    errors = []

    if not tentative:
        try:
            if vtype == 'class':
                verifyClass(iface, candidate)
            else:
                verifyObject(iface, candidate)
        except Invalid as e:
            errors.append(str(e))

    required_methods = set(iface.names(True))
    provided_methods = set(dir(candidate))

    for method_name in required_methods:
        if method_name not in provided_methods:
            errors.append(f"Missing method: {method_name}")

    for method_name in required_methods.intersection(provided_methods):
        required_sig = inspect.signature(getattr(iface, method_name))
        provided_sig = inspect.signature(getattr(candidate, method_name))
        if required_sig!= provided_sig:
            errors.append(f"Incorrect signature for method {method_name}: expected {required_sig}, got {provided_sig}")

    required_attributes = iface.names(False)
    for attr_name in required_attributes:
        if not hasattr(candidate, attr_name):
            errors.append(f"Missing attribute: {attr_name}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

def verifyObject(iface, candidate, tentative=False):
    from zope.interface import providedBy, Invalid, verify
    import inspect

    errors = []

    if not tentative and not iface.providedBy(candidate):
        errors.append(f"Candidate does not claim to provide {iface}")

    for name in iface.names():
        if not hasattr(candidate, name):
            errors.append(f"Missing attribute or method: {name}")
            continue

        attr = getattr(candidate, name)
        if callable(attr) and name in iface:
            spec = inspect.getfullargspec(attr)
            required_args = len(spec.args) - len(spec.defaults or [])
            expected_args = len(iface[name].getSignatureInfo()['required'])
            if required_args!= expected_args:
                errors.append(f"Incorrect number of arguments for {name}: expected {expected_args}, got {required_args}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

def verifyClass(iface, candidate, tentative=False):
    if not hasattr(candidate, '__implements__'):
        return False
    implemented_interfaces = candidate.__implements__
    if tentative:
        return iface in implemented_interfaces
    return iface in implemented_interfaces and all(hasattr(candidate, attr) for attr in dir(iface) if not attr.startswith('__'))

