import functools
import time

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def decorator(func):
        cache = {}
        hits = misses = 0

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            key = args if typed else tuple(args)
            if kwargs:
                key += tuple(sorted(kwargs.items()))
            now = timer()
            if key in cache:
                result, expiry = cache[key]
                if now < expiry:
                    hits += 1
                    return result
                else:
                    del cache[key]
            misses += 1
            result = func(*args, **kwargs)
            cache[key] = (result, now + ttl)
            if len(cache) > maxsize:
                oldest_key = min(cache, key=lambda k: cache[k][1])
                del cache[oldest_key]
            return result

        def cache_clear():
            nonlocal cache, hits, misses
            cache = {}
            hits = misses = 0

        def cache_info():
            return functools._CacheInfo(hits, misses, maxsize, len(cache))

        wrapper.cache_clear = cache_clear
        wrapper.cache_info = cache_info
        return wrapper

    return decorator

def cached(cache, key=hashkey, lock=None):
	def decorator(func):
		def wrapper(*args, **kwargs):
			k = key(*args, **kwargs)
			if k in cache:
				return cache[k]
			if lock is not None:
				with lock:
					if k not in cache:
						cache[k] = func(*args, **kwargs)
			else:
				cache[k] = func(*args, **kwargs)
			return cache[k]
		return wrapper
	return decorator

