def is_ipv4(target):
    parts = target.split('.')
    if len(parts)!= 4:
        return False
    for part in parts:
        if not part.isdigit():
            return False
        num = int(part)
        if num < 0 or num > 255:
            return False
        if part!= str(num):
            return False
    return True

def find_roots(graph, prop, roots=None):
    if roots is None:
        roots = set()
    children = set()
    for s, p, o in graph.triples((None, prop, None)):
        children.add(s)
        if o not in children:
            roots.add(o)
    return roots - children

