def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    import re
    tags = set()
    code_block = False
    result = []
    i = 0
    while i < len(text):
        if text[i:i+3] == '```':
            code_block = not code_block
            result.append(text[i:i+3])
            i += 3
        elif not code_block and text[i] == '#':
            match = re.match(r'#(\w+)', text[i:])
            if match:
                tag = match.group(1)
                tags.add(tag)
                if replacer:
                    result.append(replacer(tag))
                else:
                    result.append(f'#{tag}')
                i += len(match.group(0))
        else:
            result.append(text[i])
            i += 1
    return tags, ''.join(result)

